'use strict';
const $=id=>document.getElementById(id);
const state={mode:'deal',inn:'',company:null,target:null,pharmacy:null,createCompany:false,companies:[],pharmacies:[],supportType:null,result:null,epoch:0};
let reference=null,autoDealTitle='';
const noun=()=>state.mode==='deal'?'сделку':'заявку';
function show(id,visible){$(id).hidden=!visible;}
function enable(id,active){for(const field of $(id).querySelectorAll('input,select,textarea'))field.disabled=!active;}
function text(tag,value,className){const node=document.createElement(tag);node.textContent=value;if(className)node.className=className;return node;}
function error(message){$('error').textContent=message;show('error',Boolean(message));if(message)$('error').scrollIntoView({block:'center',behavior:'smooth'});}
function progress(message){$('progress').textContent=message;show('progress',Boolean(message));}
async function api(path,data){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Повторите попытку.');return result;}
function lookupData(){return {source:'crm',inn:state.inn};}
function clearResults(){state.epoch++;state.company=null;state.target=state.mode==='deal'&&!$('inn').value.trim()?'title':null;state.pharmacy=null;state.result=null;state.createCompany=false;state.companies=[];$('bindPoint').checked=false;$('bindPoint').disabled=true;$('prefillPoint').checked=false;show('pointPrefill',false);$('selectionSummary').replaceChildren();show('selectionSection',false);for(const id of ['companyPicker','unknownCompany','scopeSection','pharmacySection','entrySection','reviewSection','doneSection'])show(id,false);show('entrySection',state.mode==='deal');$('lookupButton').disabled=false;progress('');}

function option(label,description,handler){const button=document.createElement('button');button.type='button';button.className='result-option';button.append(text('strong',label));if(description)button.append(text('span',description));button.addEventListener('click',handler);return button;}
function companySummary(container,company){container.replaceChildren(text('strong','🏢 '+company.title),text('p','ИНН: '+state.inn),text('p',state.createCompany?'Создадим новую фирму':'Аптек в базе: '+company.pharmacy_count,'hint'));}
function setCompany(company){state.company=company;state.target='company';state.pharmacy=null;$('bindPoint').checked=false;$('bindPoint').disabled=company.pharmacy_count===0;show('companyPicker',false);show('unknownCompany',false);show('pharmacySection',false);show('entrySection',true);show('scopeSection',true);companySummary($('companySummary'),company);$('scopeHeading').textContent='🏪 Аптека';show('noPharmacies',company.pharmacy_count===0);defaultTitle();selectionSummary();sync();error('');}
function defaultTitle(pharmacy=null){if(state.mode!=='deal')return;const input=$('dealTitle');if(input.value.trim()&&input.value!==autoDealTitle)return;const name=pharmacy?.title||state.company?.title;if(name){autoDealTitle='План: '+name;input.value=autoDealTitle;}}

async function lookup(event){event?.preventDefault();error('');const inn=$('inn').value.trim();if(!/^[0-9]{9}$/.test(inn)){error('Введите ИНН из 9 цифр.');$('inn').focus();return;}clearResults();state.inn=inn;const epoch=state.epoch;$('lookupButton').disabled=true;progress('Подождите, ищу фирму по ИНН…');try{const result=await api('/api/lookup',lookupData());if(epoch!==state.epoch)return;state.companies=result.companies;if(result.companies.length===1)setCompany(result.companies[0]);else if(result.companies.length>1){$('companyChoices').replaceChildren(...result.companies.map(company=>option(company.title,'Аптек в базе: '+company.pharmacy_count,()=>setCompany(company))));show('companyPicker',true);}else{show('unknownCompany',true);show('creationConsent',true);show('companyNameForm',false);$('companyName').value='';}}catch(err){if(epoch===state.epoch)error(err.message);}finally{if(epoch===state.epoch){progress('');$('lookupButton').disabled=false;}}}
function selectionSummary(){if(state.target==='title'||!state.company){$('selectionSummary').replaceChildren();show('selectionSection',false);return;}show('selectionSection',true);const company=state.company;const container=$('selectionSummary');container.replaceChildren(text('strong',state.target==='company'?'🏢 Сделка / заявка на фирму':state.target==='new_pharmacy'?'🏪 Добавление новой аптеки':'🏪 '+state.pharmacy.title));container.append(text('p','Фирма: '+company.title),text('p','ИНН: '+state.inn));if(state.target==='company')container.append(text('p',state.mode==='deal'?'Сделка на фирму целиком.':'Заявка на фирму целиком.','hint'));if(state.pharmacy){container.append(text('p','FOM ID: '+(state.pharmacy.fom_id||'не указан'),'hint'));if(state.pharmacy.address)container.append(text('p',state.pharmacy.address,'hint'));container.append(text('p','Статус: '+state.pharmacy.status,'hint'));for(const key of ['business_region','city','current_program'])if(state.pharmacy[key])container.append(text('p',state.pharmacy[key],'hint'));}}
function setTarget(target,pharmacy=null){$('prefillPoint').checked=false;state.target=target;state.pharmacy=pharmacy;show('scopeSection',Boolean(state.company));show('pharmacySection',false);show('reviewSection',false);show('entrySection',true);defaultTitle(pharmacy);selectionSummary();sync();$('entrySection').scrollIntoView({block:'start',behavior:'smooth'});}
async function pharmacyList(){const epoch=state.epoch;error('');progress('Подождите, загружаю список аптек…');$('bindPoint').disabled=true;try{const result=await api('/api/pharmacies',{...lookupData(),company_id:state.company.id});if(epoch!==state.epoch)return;state.pharmacies=result.pharmacies;$('pharmacySearch').value='';show('scopeSection',false);show('pharmacySection',true);renderPharmacies();$('pharmacySection').scrollIntoView({block:'start',behavior:'smooth'});}catch(err){if(epoch===state.epoch)error(err.message);}finally{if(epoch===state.epoch){progress('');$('bindPoint').disabled=state.company.pharmacy_count===0;}}}
function renderPharmacies(){const query=$('pharmacySearch').value.toLocaleLowerCase().trim();const rows=state.pharmacies.filter(row=>[row.title,row.address,row.fom_id].join(' ').toLocaleLowerCase().includes(query));$('pharmacyResultCount').textContent=rows.length?'Найдено аптек: '+rows.length:'Аптека в этом списке не найдена. Проверьте название или ID и попробуйте другое.';$('pharmacyChoices').replaceChildren(...rows.map(row=>option(row.title,[row.fom_id?'FOM ID: '+row.fom_id:'FOM ID не указан',row.business_region,row.city,row.address||'Адрес не указан','Статус: '+row.status,row.current_program?'Текущая программа: '+row.current_program:''].join(' · '),()=>setTarget('pharmacy',row))));}
function options(id,rows,empty='Выберите из списка'){const value=$(id).value;$(id).replaceChildren(new Option(empty,''),...rows.map(row=>new Option(row.title,row.id)));if(rows.some(row=>String(row.id)===value))$(id).value=value;}
function reminderSync(){const active=state.mode==='deal'&&$('addReminder').checked;show('reminderFields',active);enable('reminderFields',active);const custom=active&&$('reminderAction').value==='other';show('customReminder',custom);enable('customReminder',custom);}
function sync(){const isDeal=state.mode==='deal';renderPointFields();show('titleEntry',isDeal);enable('titleEntry',isDeal);$('inn').required=!isDeal;show('contactSection',state.target!=='title');enable('contactSection',state.target!=='title');$('modeDeal').setAttribute('aria-pressed',String(isDeal));$('modeSupport').setAttribute('aria-pressed',String(!isDeal));$('lookupHeading').textContent=isDeal?'ИНН аптеки (необязательно)':'ИНН фирмы *';$('innHint').textContent='По ИНН покажем фирму и её аптечные точки.';$('scopeHeading').textContent='🏪 Аптека';show('newPharmacySection',state.target==='new_pharmacy');enable('newPharmacySection',state.target==='new_pharmacy');show('dealSection',isDeal);enable('dealSection',isDeal);show('supportSection',!isDeal);enable('supportSection',!isDeal);show('inactiveSection',isDeal&&Boolean(state.pharmacy?.inactive));enable('inactiveSection',isDeal&&Boolean(state.pharmacy?.inactive));if(state.pharmacy?.inactive)$('inactiveWarning').textContent='В базе у аптеки указан статус «'+state.pharmacy.status+'». Уверены, что хотите открыть сделку?';show('contactFields',$('addContact').checked);enable('contactFields',$('addContact').checked);reminderSync();$('reviewButton').textContent=isDeal?'Создать сделку →':'Отправить заявку →';$('confirmButton').textContent=isDeal?'✅ Создать сделку':'✅ Отправить заявку';if(state.target)selectionSummary();}
function mode(value){if(value==='support')show('lookupSection',true);state.mode=value;if(value==='support'&&state.target==='title')clearResults();if(value==='deal'&&!state.company&&!$('inn').value.trim())state.target='title';show('lookupSection',true);state.result=null;show('reviewSection',false);show('doneSection',false);if(state.target)show('entrySection',true);error('');sync();}
function supportTypes(){if(!reference)return;const program=$('supportProgram').value;const query=$('supportSearch').value.trim().toLocaleLowerCase();const types=reference.support.types.filter(row=>row.id!==reference.support.unknown_id&&(!program||!row.program_ids?.length||row.program_ids.includes(program))&&[row.title,...(row.aliases||[])].join(' ').toLocaleLowerCase().includes(query));$('supportTypeCount').textContent=types.length?'Вариантов: '+types.length+(types.length>35?' · первые 35, уточните поиск':''):'Не нашли проблему? Можно выбрать «Неопознанная ошибка». ';$('supportTypes').replaceChildren(...types.slice(0,35).map(row=>option(row.title,'',()=>selectSupportType(row))));}
function selectSupportType(row){state.supportType=row;$('selectedSupportType').replaceChildren(text('strong','✓ '+row.title));show('selectedSupportType',true);$('requestTitle').value=row.id===reference.support.unknown_id?'':row.title.slice(0,100);$('requestDescription').setAttribute('placeholder',row.id===reference.support.unknown_id?'Опишите своими словами, что случилось и какая помощь нужна.':'');}
function payload(){const data={...lookupData(),mode:state.mode,target:state.target,company_id:state.company?.id||null,company_name:state.company?.title||'',deal_title:$('dealTitle').value.trim(),create_company:state.createCompany,pharmacy_id:state.pharmacy?.id||null,confirm_inactive:$('confirmInactive').checked,discussion_programs:[...document.querySelectorAll('[name=discussion_program]:checked')].map(node=>node.value),support_type:state.supportType?.id||'',support_program:$('supportProgram').value,request_title:$('requestTitle').value.trim(),request_description:$('requestDescription').value.trim()};if(state.target==='new_pharmacy')data.new_pharmacy={title:$('newTitle').value.trim(),address:$('newAddress').value.trim(),region:$('region').value,city:$('city').value,program:$('currentProgram').value};if(state.mode==='deal'&&$('addReminder').checked)data.reminder={action:$('reminderAction').value==='other'?$('reminderText').value.trim():$('reminderAction').value,deadline:$('reminderDate').value+'T'+$('reminderTime').value};if($('addContact').checked)data.contact={name:$('contactName').value.trim(),phone:$('contactPhone').value.trim()};return data;}
function group(title,lines){const node=document.createElement('div');node.className='review-group';node.append(text('h3',title));for(const line of lines.filter(Boolean))node.append(text('p',line));return node;}
function renderReview(result){const groups=[];if(result.pharmacy){const p=result.pharmacy;groups.push(group('🏪 Аптека',[p.title,p.fom_id?'FOM ID: '+p.fom_id:'',p.address,p.region||p.business_region,p.city,p.current_program,p.program?'Текущая программа: '+p.program:'','Статус: '+p.status,result.target==='new_pharmacy'?'Добавим новую аптеку в базу':'']));}if(result.company)groups.push(group('🏢 Компания / Фирма',[result.company.title,'ИНН: '+result.inn,result.company.create?'Создадим новую фирму':'Используем найденную фирму']));if(result.contact)groups.push(group('👤 Контактное лицо',[result.contact.name,result.contact.phone]));groups.push(group(result.mode==='deal'?'📋 Сделка':'🛠 Заявка',[result.title,'Воронка: '+result.pipeline,'Стадия: '+result.stage,result.programs?'Обсудить: '+result.programs.join(', '):'',result.support_type?'Тип обращения: '+result.support_type:'',result.description]));if(result.reminder)groups.push(group('🔔 Напоминание',[result.reminder.action,result.reminder.display]));$('reviewBody').replaceChildren(...groups);}
async function preview(event){event.preventDefault();error('');if(state.mode==='deal'&&!$('inn').value.trim())state.target='title';if($('bindPoint').checked&&!state.pharmacy){error('Выберите аптеку из списка.');return;}if((!state.company&&state.target!=='title')||!state.target){error('Сначала выберите фирму или аптеку.');return;}if(!$('entryForm').reportValidity())return;const epoch=state.epoch;const button=$('reviewButton'),label=button.textContent;button.disabled=true;button.textContent=state.mode==='deal'?'⏳ Подождите, готовим сделку…':'⏳ Подождите, готовим заявку…';progress('Подождите, готовим данные для подтверждения…');try{const result=await api('/api/preview',payload());if(epoch!==state.epoch)return;state.result=result;renderReview(result);show('entrySection',false);show('reviewSection',true);$('reviewSection').scrollIntoView({block:'start',behavior:'smooth'});}catch(err){if(epoch===state.epoch)error(err.message);}finally{button.disabled=false;button.textContent=label;if(epoch===state.epoch)progress('');}}
$('lookupForm').addEventListener('submit',lookup);
$('inn').addEventListener('input',()=>{if(state.inn!==$('inn').value.trim())clearResults();error('');});
$('createCompanyYes').addEventListener('click',()=>{show('creationConsent',false);show('companyNameForm',true);$('companyName').focus();});
$('createCompanyNo').addEventListener('click',()=>{clearResults();$('inn').value='';$('inn').focus();});
$('companyNameForm').addEventListener('submit',event=>{event.preventDefault();if(!$('companyNameForm').reportValidity())return;state.createCompany=true;setCompany({id:null,title:$('companyName').value.trim(),inn:state.inn,pharmacy_count:0});});

$('bindPoint').addEventListener('change',()=>{if($('bindPoint').checked)pharmacyList();else setTarget('company');});
$('addPharmacy').addEventListener('click',()=>{$('bindPoint').checked=false;setTarget('new_pharmacy');});
$('backToScope').addEventListener('click',()=>setCompany(state.company));
$('pharmacySearch').addEventListener('input',renderPharmacies);
$('changeSelection').addEventListener('click',()=>setCompany(state.company));
$('modeDeal').addEventListener('click',()=>mode('deal'));$('modeSupport').addEventListener('click',()=>mode('support'));
$('region').addEventListener('change',()=>options('city',reference.cities[$('region').value]||[]));
$('addReminder').addEventListener('change',reminderSync);$('reminderAction').addEventListener('change',reminderSync);$('addContact').addEventListener('change',sync);
$('supportSearch').addEventListener('input',supportTypes);$('supportProgram').addEventListener('change',()=>{state.supportType=null;show('selectedSupportType',false);supportTypes();});
$('unknownType').addEventListener('click',()=>selectSupportType(reference.support.types.find(row=>row.id===reference.support.unknown_id)));
function renderPointFields(){const row=state.pharmacy;show('changeSelection',Boolean(state.company));show('pointPrefill',Boolean(row));show('pointFields',Boolean(row)&&$('prefillPoint').checked);for(const [id,key] of [['pointRegion','business_region'],['pointCity','city'],['pointAddress','address'],['pointProgram','current_program'],['pointPhone','phone']])$(id).value=row&&$('prefillPoint').checked?(row[key]||''):'';}
$('prefillPoint').addEventListener('change',renderPointFields);
$('entryForm').addEventListener('submit',preview);
$('editButton').addEventListener('click',()=>{show('reviewSection',false);show('entrySection',true);sync();});
$('confirmButton').addEventListener('click',()=>{if(!state.result)return;show('reviewSection',false);show('doneSection',true);$('doneText').textContent=(state.mode==='deal'?'Сделка':'Заявка')+' подготовлена '+(state.target==='title'?'«'+state.result.title+'».':state.target==='company'?'на фирму «'+state.company.title+'».':'на аптеку «'+state.result.pharmacy.title+'».');state.result=null;$('doneSection').scrollIntoView({block:'start',behavior:'smooth'});});
$('startAgain').addEventListener('click',()=>{show('lookupSection',true);$('inn').value='';clearResults();$('entryForm').reset();state.supportType=null;show('selectedSupportType',false);$('inn').value='';sync();$('inn').focus();window.scrollTo({top:0,behavior:'smooth'});});
async function initialize(){try{const [data,health]=await Promise.all([fetch('/reference.json').then(r=>r.json()),fetch('/api/health').then(r=>r.json())]);reference=data;if(!health.sources.includes('crm'))error('Поиск в Б24 временно недоступен. Сделку можно подготовить по названию без ИНН.');options('region',reference.regions);options('city',[]);options('currentProgram',reference.programs);options('supportProgram',reference.support.programs,'Все программы');$('discussionPrograms').replaceChildren(...reference.discussion_programs.map(row=>{const label=document.createElement('label');label.className='check';const input=document.createElement('input');input.type='checkbox';input.name='discussion_program';input.value=row.id;label.append(input,text('span',row.title));return label;}));for(let minutes=0;minutes<1440;minutes+=30){const value=String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0');$('reminderTime').append(new Option(value,value));}$('reminderTime').value='18:00';$('reminderDate').min=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tashkent',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());supportTypes();sync();}catch(err){error('Не удалось загрузить списки. Обновите тестовую форму.');}}
clearResults();show('lookupSection',true);initialize();

$('newTitle').addEventListener('input',()=>defaultTitle({title:$('newTitle').value.trim()}));
